// Environment-gated debug logger — no-ops in production builds
const isDev = process.env.NODE_ENV === 'development';
const debugLog = isDev ? (...args) => console.log(...args) : () => {};

const getUserId = (user) => String(user?.id || user?._id || user?.userId || '');
const normalizeId = (id) => String(id || '');

// Helper to resolve avatar URL from backend profilePicture (might be string, object, or JSON string)
const resolveAvatarUrl = (profilePicture) => {
  if (!profilePicture) return null;
  
  // If it's already a valid URL, return it
  if (typeof profilePicture === 'string' && (profilePicture.startsWith('http://') || profilePicture.startsWith('https://'))) {
    return profilePicture;
  }
  
  // If it's a string that looks like JSON, try to parse it
  if (typeof profilePicture === 'string' && (profilePicture.startsWith('{') || profilePicture.startsWith('['))) {
    try {
      const parsed = JSON.parse(profilePicture);
      if (parsed.url) {
        return parsed.url.startsWith('http') ? parsed.url : getUploadUrl(parsed.url);
      }
    } catch (e) {
      // Not valid JSON, treat as path
    }
  }
  
  // If it's an object with url property
  if (typeof profilePicture === 'object' && profilePicture.url) {
    return profilePicture.url.startsWith('http') ? profilePicture.url : getUploadUrl(profilePicture.url);
  }
  
  // If it's a simple string path, treat as upload path
  if (typeof profilePicture === 'string') {
    return getUploadUrl(profilePicture);
  }
  
  return null;
};

const typingBlink = keyframes`
  0% { opacity: 0.3; transform: translateY(0px); }
  50% { opacity: 1; transform: translateY(-2px); }
  100% { opacity: 0.3; transform: translateY(0px); }
`;

const inferMessageTypeFromContent = (content = '', explicitType = null, metadata = {}) => {
  if (explicitType && explicitType !== 'text') return explicitType;
  const mimeType = String(metadata?.mimeType || metadata?.mimetype || '').toLowerCase();
  const fileName = String(metadata?.filename || metadata?.fileName || metadata?.name || '').toLowerCase();
  if (mimeType.startsWith('image/')) return 'image';
  if (mimeType.startsWith('video/')) return 'video';
  if (mimeType.startsWith('audio/')) return 'audio';
  if (mimeType && !mimeType.startsWith('text/')) return 'file';
  if (/\.(jpe?g|png|gif|webp|heic|bmp|svg|tiff?)$/.test(fileName)) return 'image';
  if (/\.(mp4|mov|avi|webm|mkv|m4v|3gp)$/.test(fileName)) return 'video';
  if (/\.(mp3|wav|ogg|aac|flac|m4a|wma)$/.test(fileName)) return 'audio';
  const value = String(content || '').trim().toLowerCase().split('?')[0].split('#')[0];
  if (value.startsWith('data:image/')) return 'image';
  if (value.startsWith('data:video/')) return 'video';
  if (value.startsWith('data:audio/')) return 'audio';
  if (/\/image\/upload\//.test(value)) return 'image';
  if (/\/video\/upload\//.test(value)) return 'video';
  if (/\.(jpe?g|png|gif|webp|heic|bmp|svg|tiff?)$/.test(value) || /image|photo|img/.test(value)) return 'image';
  if (/\.(mp4|mov|avi|webm|mkv|m4v|3gp)$/.test(value) || /video|vid/.test(value)) return 'video';
  if (/\.(mp3|wav|ogg|aac|flac|m4a|wma)$/.test(value) || /audio|voice/.test(value)) return 'audio';
  if (value.startsWith('http://') || value.startsWith('https://') || value.startsWith('/uploads/') || value.startsWith('data:')) return 'file';
  return explicitType || 'text';
};

// Swipeable Conversation Item Component
const SwipeableConversationItem = ({ 
  children, 
  onSwipeLeft, 
  onSwipeRight, 
  conversationId,
  swipedId,
  setSwipedId,
  hasUnread
}) => {
  const [translateX, setTranslateX] = useState(0);
  
  const handlers = useSwipeable({
    onSwiping: (eventData) => {
      const deltaX = eventData.deltaX;
      // Limit swipe distance
      const maxSwipe = 80;
      const newTranslate = Math.max(-maxSwipe, Math.min(maxSwipe, deltaX));
      setTranslateX(newTranslate);
    },
    onSwipedLeft: () => {
      if (translateX < -40) {
        setSwipedId(conversationId);
        setTranslateX(-80);
      } else {
        setTranslateX(0);
      }
    },
    onSwipedRight: () => {
      if (translateX > 40 && hasUnread) {
        onSwipeRight();
        setTranslateX(0);
      } else {
        setTranslateX(0);
      }
    },
    onTouchEndOrOnMouseUp: () => {
      if (Math.abs(translateX) < 40) {
        setTranslateX(0);
      }
    },
    trackMouse: false,
    trackTouch: true,
    preventScrollOnSwipe: true,
    delta: 10
  });

  // Reset when another item is swiped
  React.useEffect(() => {
    if (swipedId && swipedId !== conversationId) {
      setTranslateX(0);
    }
  }, [swipedId, conversationId]);

  return (
    <Box sx={{ position: 'relative', overflow: 'hidden' }}>
      {/* Background actions */}
      <Box sx={{
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        display: 'flex',
        alignItems: 'stretch'
      }}>
        {/* Left side - Mark as read (green) */}
        <Box sx={{
          flex: 1,
          background: hasUnread ? 'linear-gradient(90deg, #00ff88, #00cc6a)' : 'rgba(255,255,255,0.1)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-start',
          pl: 2,
          color: hasUnread ? '#000' : 'rgba(255,255,255,0.3)'
        }}>
          <DoneAllIcon />
        </Box>
        {/* Right side - Delete (red) */}
        <Box 
          sx={{
            width: 80,
            background: 'linear-gradient(90deg, #ff4444, #cc3333)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#fff',
            cursor: 'pointer'
          }}
          onClick={() => {
            if (swipedId === conversationId) {
              onSwipeLeft();
            }
          }}
        >
          <DeleteIcon />
        </Box>
      </Box>
      
      {/* Foreground content */}
      <Box
        {...handlers}
        sx={{
          transform: `translateX(${translateX}px)`,
          transition: translateX === 0 ? 'transform 0.2s ease-out' : 'none',
          background: 'var(--bg-secondary, #1a1a22)',
          position: 'relative',
          zIndex: 1
        }}
      >
        {children}
      </Box>
    </Box>
  );
};

const ChatSystem = ({
  recipientId: propRecipientId = null,
  recipientName: propRecipientName = null,
  recipientAvatar: propRecipientAvatar = null,
  initialConversationId: propInitialConversationId = null
}) => {
  const { socket, isConnected } = useSocket();
  const { user } = useAuth();
  const currentUserId = getUserId(user);
  const { startCall: triggerCall } = useCall();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();

  // Recipient / navigation state
  const routeState = location?.state || {};
  const targetRecipientId = propRecipientId || routeState.recipientId || null;
  const targetRecipientName = propRecipientName || routeState.recipientName || null;
  const targetRecipientAvatar = propRecipientAvatar || routeState.recipientAvatar || null;
  const initialConversationId = propInitialConversationId || routeState.conversationId || routeState.conversationID || null;
  
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [startingConversation, setStartingConversation] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [remoteTyping, setRemoteTyping] = useState(false);
  const [showMobileChat, setShowMobileChat] = useState(false);
  const [typingConversations, setTypingConversations] = useState([]);
  
  // Payment / Escrow states
  const [paymentSheetOpen, setPaymentSheetOpen] = useState(false);
  const [activeEscrow, setActiveEscrow] = useState(null);
  const [escrowLoading, setEscrowLoading] = useState(false);
  
  // Milestone request states
  const [milestoneDialogOpen, setMilestoneDialogOpen] = useState(false);
  const [pendingMilestones, setPendingMilestones] = useState([]);
  const [isProvider, setIsProvider] = useState(false); // Is current user a provider?
  
  // Menu state
  const [menuAnchorEl, setMenuAnchorEl] = useState(null);
  const menuOpen = Boolean(menuAnchorEl);

  // Emoji picker (lightweight)
  const [emojiAnchorEl, setEmojiAnchorEl] = useState(null);
  const emojiMenuOpen = Boolean(emojiAnchorEl);
  
  // Scroll-to-bottom FAB state
  const [showScrollButton, setShowScrollButton] = useState(false);
  
  // Mobile action drawer for input buttons
  const [moreActionsOpen, setMoreActionsOpen] = useState(false);
  
  // Dispute dialog state
  const [disputeDialogOpen, setDisputeDialogOpen] = useState(false);
  const [disputeReason, setDisputeReason] = useState('');
  
  // Message long-press menu state
  const [messageMenuAnchor, setMessageMenuAnchor] = useState(null);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const longPressTimer = useRef(null);
  
  // Attachment preview state
  const [attachmentPreview, setAttachmentPreview] = useState(null);
  const [pendingFile, setPendingFile] = useState(null);
  
  // Swipe action state for conversations
  const [swipedConversationId, setSwipedConversationId] = useState(null);
  
  const messagesEndRef = useRef(null);
  const messagesContainerRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const fileInputRef = useRef(null);
  const hasBootstrappedRef = useRef(false);
  const prevConversationIdRef = useRef(null);
  // Dedup ref — prevents double-processing when message arrives via both conversation and user rooms
  const processedMsgIds = useRef(new Set());
  // Stable ref for selected conversation — socket handlers read this instead of the
  // state variable, so the useEffect that registers handlers doesn't need
  // selectedConversation in its dependency array (which would cause handler
  // teardown/re-registration on every online-status or escrow-state change).
  const selectedConversationRef = useRef(null);
  useEffect(() => {
    selectedConversationRef.current = selectedConversation;
  }, [selectedConversation]);

  useEffect(() => {
    if (user) loadConversations();
  }, [user]);

  // After conversations load, query online status for each participant
  useEffect(() => {
    if (!socket || !isConnected || conversations.length === 0) return;
    const participantIds = [...new Set(conversations
      .map((conv) => normalizeId(conv.participantId))
      .filter(Boolean))];

    if (participantIds.length > 0) {
      socket.emit('get_users_status', { userIds: participantIds });
    }

    // Only run when conversations list length changes (initial load / refresh), not on every update
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [socket, isConnected, conversations.length]);

  // Track conversation ID separately so room join/leave only fires on actual
  // conversation switches — not on every object-reference change (online status,
  // escrow updates, etc.) which would cause leave+rejoin and lost messages.
  const selectedConversationId = selectedConversation?.id || null;

  useEffect(() => {
    if (selectedConversationId) {
      loadMessages(selectedConversationId);
      if (socket && isConnected) {
        socket.emit('join_conversation', selectedConversationId);
      }
      setRemoteTyping(false);
    }
    // Cleanup: leave conversation room when switching or unmounting
    return () => {
      if (selectedConversationId && socket && isConnected) {
        socket.emit('leave_conversation', selectedConversationId);
      }
    };
  }, [selectedConversationId, socket, isConnected]);

  // Emit typing_stop when switching conversations or unmounting to avoid stuck indicators
  useEffect(() => {
    const prevId = prevConversationIdRef.current;
    if (prevId && prevId !== selectedConversationId && socket && isConnected) {
      socket.emit('typing_stop', { conversationId: prevId });
    }
    prevConversationIdRef.current = selectedConversationId;

    return () => {
      if (prevConversationIdRef.current && socket && isConnected) {
        socket.emit('typing_stop', { conversationId: prevConversationIdRef.current });
      }
    };
  }, [selectedConversationId, socket, isConnected]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Handle scroll position for scroll-to-bottom FAB
  const handleMessagesScroll = (e) => {
    const { scrollTop, scrollHeight, clientHeight } = e.target;
    const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
    setShowScrollButton(!isNearBottom);
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Auto-scroll to bottom when keyboard appears (mobile viewport resize)
  useEffect(() => {
    const handleViewportResize = () => {
      if (window.visualViewport && selectedConversation) {
        // When keyboard appears, viewport height decreases - scroll to bottom
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
      }
    };

    window.visualViewport?.addEventListener('resize', handleViewportResize);
    return () => window.visualViewport?.removeEventListener('resize', handleViewportResize);
  }, [selectedConversation]);

  // Socket listeners — use selectedConversationRef (stable ref) instead of
  // selectedConversation (state) so that this effect only re-runs when the
  // socket itself changes, not on every conversation-state mutation.
  useEffect(() => {
    if (!socket || !isConnected) return;

    const handleNewMessage = (messageData) => {
      // Dedup: skip if already processed (message received via both conversation + user rooms)
      const msgId = String(messageData.id || '');
      if (msgId && processedMsgIds.current.has(msgId)) return;
      if (msgId) {
        processedMsgIds.current.add(msgId);
        if (processedMsgIds.current.size > 200) {
          const arr = [...processedMsgIds.current];
          processedMsgIds.current = new Set(arr.slice(-100));
        }
      }

      let conversationFound = false;
      const messageTimestamp = messageData.createdAt || messageData.timestamp || new Date().toISOString();
      const currentConv = selectedConversationRef.current;

      if (currentConv && messageData.conversationId === currentConv.id) {
        setMessages((prev) => {
          // Deduplicate by message id
          if (prev.some((m) => m.id === messageData.id)) {
            return prev;
          }

          // Replace optimistic temp message if it matches
          if (String(messageData.senderId || '') === currentUserId) {
            const tempIndex = prev.findIndex(
              (m) => m.status === 'sending' &&
                normalizeId(m.senderId) === currentUserId &&
                normalizeId(m.conversationId) === normalizeId(messageData.conversationId) &&
                m.content === messageData.content
            );
            if (tempIndex >= 0) {
              const next = [...prev];
              next[tempIndex] = { ...messageData, createdAt: messageTimestamp, status: 'sent' };
              return next;
            }
          }

          return [...prev, { ...messageData, createdAt: messageTimestamp }];
        });

        if (String(messageData.senderId || '') !== currentUserId) {
          setRemoteTyping(false);
          markConversationRead(messageData.conversationId);
          // Counteract the global unread increment from SocketContext — the user
          // is actively viewing this conversation, so it's instantly read.
          dispatch(decrementUnreadMessages(1));
        }
      }

      setConversations((prev) =>
        sortConversations(
          prev.map((conv) => {
            if (conv.id !== messageData.conversationId) return conv;
            conversationFound = true;
            const isOwn = String(messageData.senderId || '') === currentUserId;
            const isActive = currentConv?.id === conv.id;
            const resolvedType = inferMessageTypeFromContent(messageData.content, messageData.messageType, messageData.metadata);
            return {
              ...conv,
              lastMessage: formatMessagePreview(messageData.content, resolvedType),
              lastMessageTime: messageTimestamp,
              unreadCount: isOwn || isActive ? 0 : (conv.unreadCount || 0) + 1
            };
          })
        )
      );

      if (!conversationFound) {
        // Fetch latest conversations to include new thread
        loadConversations({ silent: true });
      }
    };

    socket.on('new_message', handleNewMessage);
    const handleTypingStart = ({ conversationId }) => {
      setTypingConversations((prev) => (prev.includes(conversationId) ? prev : [...prev, conversationId]));
      if (selectedConversationRef.current?.id === conversationId) {
        setRemoteTyping(true);
      }
    };
    const handleTypingStop = ({ conversationId }) => {
      setTypingConversations((prev) => prev.filter((id) => id !== conversationId));
      if (selectedConversationRef.current?.id === conversationId) {
        setRemoteTyping(false);
      }
    };

    socket.on('typing_start', handleTypingStart);
    socket.on('typing_stop', handleTypingStop);

    const handleMessageDeleted = ({ messageId, conversationId }) => {
      setMessages((prev) => prev.filter((msg) => String(msg.id || msg._id || '') !== String(messageId)));

      // Refresh conversation previews when the affected thread changes
      if (normalizeId(selectedConversationRef.current?.id) === normalizeId(conversationId)) {
        loadConversations({ silent: true });
      }
    };

    socket.on('message_deleted', handleMessageDeleted);

    const handleJoinError = (payload) => {
      const message = payload?.error || 'Failed to join conversation';
      toast.error(message);
    };

    const handleMessageError = (payload) => {
      const reason = payload?.message || payload?.error || 'Failed to send message';
      if (payload?.error === 'subscription_required') {
        toast.warning(reason);
        navigate('/subscription');
        return;
      }
      toast.error(reason);
    };

    const handleMessageBlocked = (payload) => {
      toast.warning(payload?.error || 'Message blocked due to policy violation');
    };

    socket.on('join_error', handleJoinError);
    socket.on('message_error', handleMessageError);
    socket.on('message_blocked', handleMessageBlocked);

    // Handle read receipts — other participant read our messages
    const handleMessageRead = ({ conversationId, userId: readerId, timestamp }) => {
      if (String(readerId || '') === currentUserId) return; // Ignore our own read events
      if (selectedConversationRef.current?.id === conversationId) {
        setMessages((prev) =>
          prev.map((msg) =>
            String(msg.senderId || '') === currentUserId && !msg.readAt
              ? { ...msg, readAt: timestamp }
              : msg
          )
        );
      }
    };
    socket.on('message_read', handleMessageRead);

    // Handle user online/offline status updates
    const handleUserStatus = ({ userId, isOnline }) => {
      debugLog('👤 User status update:', userId, isOnline ? 'online' : 'offline');
      const normalizedTargetUserId = normalizeId(userId);
      setConversations((prev) =>
        prev.map((conv) =>
          normalizeId(conv.participantId) === normalizedTargetUserId
            ? { ...conv, participantOnline: isOnline }
            : conv
        )
      );
      // Update selected conversation if it's with this user
      if (normalizeId(selectedConversationRef.current?.participantId) === normalizedTargetUserId) {
        setSelectedConversation((prev) =>
          prev ? { ...prev, participantOnline: isOnline } : prev
        );
      }
    };
    socket.on('user_status', handleUserStatus);

    const handleUsersStatus = ({ users = [] }) => {
      if (!Array.isArray(users) || users.length === 0) return;

      const statusMap = new Map(users.map((entry) => [normalizeId(entry.userId), !!entry.isOnline]));

      setConversations((prev) =>
        prev.map((conv) => {
          const participantId = normalizeId(conv.participantId);
          if (!participantId || !statusMap.has(participantId)) return conv;
          return {
            ...conv,
            participantOnline: statusMap.get(participantId)
          };
        })
      );

      setSelectedConversation((prev) => {
        if (!prev?.participantId) return prev;
        const participantId = normalizeId(prev.participantId);
        if (!statusMap.has(participantId)) return prev;
        return {
          ...prev,
          participantOnline: statusMap.get(participantId)
        };
      });
    };

    socket.on('users_status', handleUsersStatus);

    return () => {
      socket.off('new_message', handleNewMessage);
      socket.off('typing_start', handleTypingStart);
      socket.off('typing_stop', handleTypingStop);
      socket.off('message_deleted', handleMessageDeleted);
      socket.off('join_error', handleJoinError);
      socket.off('message_error', handleMessageError);
      socket.off('message_blocked', handleMessageBlocked);
      socket.off('user_status', handleUserStatus);
      socket.off('users_status', handleUsersStatus);
      socket.off('message_read', handleMessageRead);
    };
  }, [socket, isConnected, currentUserId, navigate]);

  // Bootstrap target recipient or conversation from props / navigation state
  useEffect(() => {
    debugLog('💬 Bootstrap effect:', { user: !!user, loading, hasBootstrapped: hasBootstrappedRef.current, targetRecipientId, initialConversationId });
    
    if (!user || loading || hasBootstrappedRef.current) return;

    const tryBootstrap = async () => {
      try {
        if (targetRecipientId) {
          debugLog('💬 Bootstrapping with targetRecipientId:', targetRecipientId);
          hasBootstrappedRef.current = true;
          await startConversationWithRecipient(targetRecipientId);
        } else if (initialConversationId) {
          const existing = conversations.find(c => c.id === initialConversationId);
          if (existing) {
            hasBootstrappedRef.current = true;
            selectConversation(existing);
          }
        }
      } catch (error) {
        console.error('Bootstrap chat failed:', error);
      }
    };

    tryBootstrap();
  }, [user, loading, targetRecipientId, initialConversationId, conversations]);

  const sortConversations = (list = []) =>
    [...list].sort((a, b) => new Date(b.lastMessageTime || b.createdAt || 0) - new Date(a.lastMessageTime || a.createdAt || 0));

  const resolveMediaUrl = (url) => {
    if (!url) return '';
    if (url.startsWith('http')) return url;
    return getUploadUrl(url);
  };

  /**
   * Format a message preview for the conversation list sidebar.
   * Shows friendly labels for non-text messages instead of raw URLs.
   */
  const formatMessagePreview = (content, messageType) => {
    const resolvedType = inferMessageTypeFromContent(content, messageType);
    if (!resolvedType || resolvedType === 'text') return content || '';
    switch (resolvedType) {
      case 'image': return '📷 Photo';
      case 'video': return '🎬 Video';
      case 'file': return '📎 File';
      case 'audio': return '🎵 Audio';
      case 'location': return '📍 Location';
      case 'contact': return '👤 Contact';
      default: return content || '';
    }
  };

  const loadConversations = async ({ silent = false } = {}) => {
    try {
      debugLog('🔄 Loading conversations...');
      if (!silent) setLoading(true);
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/chat/conversations`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      debugLog('📡 Conversations API response:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json();
        debugLog('📋 Raw conversations data:', data);
        // Transform API response to expected frontend format
        const transformedConversations = (data.conversations || []).map(conv => {
          // Use lastMessageType from server for accurate preview; fall back to inference from content
          const preview = formatMessagePreview(conv.lastMessage, conv.lastMessageType);
          return {
            id: conv.id,
            participantName: conv.otherUser?.username || 'Unknown',
            participantAvatar: resolveAvatarUrl(conv.otherUser?.profilePicture),
            participantOnline: false, // Will be updated via socket get_user_status
            participantVerified: (conv.otherUser?.verificationTier || 0) >= 2,
            participantId: normalizeId(conv.otherUser?.id),
            lastMessage: preview,
            lastMessageTime: conv.lastMessageTime,
            unreadCount: conv.unreadCount || 0,
            hasActiveEscrow: conv.hasActiveEscrow || false,
            createdAt: conv.createdAt
          };
        });
        debugLog('🔄 Transformed conversations:', transformedConversations);
        const sorted = sortConversations(transformedConversations);
        setConversations(sorted);
        debugLog('✅ Conversations loaded successfully:', sorted.length, 'conversations');
        return sorted;
      } else {
        console.error('❌ Conversations API failed:', response.status, response.statusText);
      }
    } catch (error) {
      console.error('❌ Failed to load conversations:', error);
      toast.error('Unable to load conversations right now.');
    } finally {
      if (!silent) setLoading(false);
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      debugLog('📨 Loading messages for conversation:', conversationId);
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/chat/messages/${conversationId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      debugLog('📨 Messages API response:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json();
        debugLog('💬 Messages data:', data);
        setMessages(data.messages || []);
        debugLog('💬 Messages set to state:', data.messages?.length || 0);
        setConversations(prev => prev.map(c => c.id === conversationId ? { ...c, unreadCount: 0 } : c));
        // Note: markConversationRead is already called by `selectConversation`; no need to call again here.
      }
    } catch (error) {
      console.error('Failed to load messages:', error);
      toast.error('Unable to load messages right now.');
    }
  };

  const startConversationWithRecipient = async (recipientId) => {
    debugLog('💬 startConversationWithRecipient called with:', recipientId, typeof recipientId);
    
    if (!recipientId || startingConversation) {
      debugLog('💬 Skipping - no recipientId or already starting:', { recipientId, startingConversation });
      return null;
    }
    
    const existing = conversations.find(c => normalizeId(c.participantId) === normalizeId(recipientId));
    if (existing) {
      debugLog('💬 Found existing conversation:', existing.id);
      selectConversation(existing);
      return existing;
    }

    try {
      setStartingConversation(true);
      const token = localStorage.getItem('token');
      
      // Ensure recipientId is sent correctly
      const payload = { otherUserId: recipientId };
      const apiUrl = `${API_BASE_URL}/chat/start`;
      debugLog('💬 Sending chat/start with payload:', payload);
      debugLog('💬 API URL:', apiUrl, '| API_BASE_URL:', API_BASE_URL);
      
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        console.error('💬 Chat start failed:', response.status, errorData);
        
        // Handle subscription limit error - redirect to subscribe page
        if (response.status === 403 && errorData.error === 'subscription_required') {
          toast.warning('You have reached your free messaging limit. Subscribe to message unlimited people! 🌟');
          navigate('/subscription');
          return null;
        }
        
        throw new Error(errorData.message || 'Failed to start conversation');
      }
      
      const data = await response.json();
      debugLog('💬 Chat start success:', data);
      
      const convList = await loadConversations({ silent: true });
      const created = convList?.find(c => normalizeId(c.participantId) === normalizeId(recipientId) || normalizeId(c.id) === normalizeId(data.conversationId));
      if (created) {
        selectConversation(created);
      }
      return created || null;
    } catch (error) {
      console.error('Failed to start conversation:', error);
      toast.error(error.message || 'Unable to start conversation right now.');
      return null;
    } finally {
      setStartingConversation(false);
    }
  };

  const sendMessagePayload = async ({ content, messageType = 'text', metadata = {} }) => {
    if (!content || !selectedConversation) return;

    const tempId = `temp-${Date.now()}`;
    const tempMessage = {
      id: tempId,
      content,
      senderId: currentUserId,
      conversationId: selectedConversation.id,
      createdAt: new Date().toISOString(),
      status: 'sending',
      messageType,
      metadata
    };
    setMessages(prev => [...prev, tempMessage]);

    try {
      debugLog('📤 Sending message payload:', { content, messageType, metadata }, 'to conversation:', selectedConversation.id);
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/chat/send`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          conversationId: selectedConversation.id,
          content,
          messageType,
          metadata
        })
      });

      debugLog('📤 Send API response:', response.status);
      if (response.ok) {
        const data = await response.json();
        debugLog('📤 Message sent successfully, data:', data);
        const saved = data.message;
        if (saved) {
          setMessages(prev =>
            prev.map(msg =>
              msg.id === tempId ? { ...saved, status: 'sent' } : msg
            )
          );
          setConversations(prev =>
            prev
              .map(conv => conv.id === selectedConversation.id
                ? { ...conv, lastMessage: formatMessagePreview(saved.content, messageType), lastMessageTime: saved.createdAt }
                : conv)
              .sort((a, b) => new Date(b.lastMessageTime || b.createdAt || 0) - new Date(a.lastMessageTime || a.createdAt || 0))
          );
        }
      } else {
        const errData = await response.json().catch(() => ({}));
        console.error('📤 Send failed:', response.status, response.statusText, errData);
        setMessages(prev => prev.map(msg => msg.id === tempId ? { ...msg, status: 'failed' } : msg));
        if (errData?.error === 'subscription_required') {
          toast.warning(errData?.message || 'Messaging limit reached. Subscribe to continue.');
          navigate('/subscription');
        } else {
          toast.error(errData?.message || errData?.error || 'Failed to send message.');
        }
      }
    } catch (error) {
      console.error('Failed to send message:', error);
      setMessages(prev => prev.map(msg => msg.id === tempId ? { ...msg, status: 'failed' } : msg));
      toast.error('Failed to send message.');
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;
    const messageContent = newMessage.trim();
    setNewMessage('');
    await sendMessagePayload({ content: messageContent, messageType: 'text' });
  };

  // File validation constants
  const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
  const ALLOWED_FILE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'audio/mpeg', 'audio/wav', 'application/pdf'];

  // Show preview before uploading attachment
  const handleFilePreview = (event) => {
    const file = event.target.files?.[0];
    if (!file || !selectedConversation) return;
    
    // Validate file size
    if (file.size > MAX_FILE_SIZE) {
      alert('File is too large. Maximum size is 10MB.');
      event.target.value = '';
      return;
    }
    
    // Validate file type
    if (!ALLOWED_FILE_TYPES.includes(file.type)) {
      alert('File type not supported. Allowed: images, video, audio, PDF.');
      event.target.value = '';
      return;
    }
    
    // Store the file for later upload
    setPendingFile(file);
    
    // Generate preview for images
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => setAttachmentPreview(e.target.result);
      reader.readAsDataURL(file);
    } else {
      // For non-images, show generic preview
      setAttachmentPreview('file');
    }
    
    // Clear the input
    event.target.value = '';
  };

  const handleFileSelect = async (event) => {
    const file = event.target.files?.[0];
    if (!file || !selectedConversation) return;
    
    // Validate file size and type
    if (file.size > MAX_FILE_SIZE) {
      alert('File is too large. Maximum size is 10MB.');
      event.target.value = '';
      return;
    }
    if (!ALLOWED_FILE_TYPES.includes(file.type)) {
      alert('File type not supported.');
      event.target.value = '';
      return;
    }
    
    try {
      const token = localStorage.getItem('token');
      const formData = new FormData();
      formData.append('file', file);
      const uploadRes = await fetch(`${API_BASE_URL}/uploads/chat-attachment`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` },
        body: formData
      });
      if (!uploadRes.ok) throw new Error('Upload failed');
      const data = await uploadRes.json();
      const fileType = data.fileType || (file.type.startsWith('video/') ? 'video' : file.type.startsWith('image/') ? 'image' : 'file');
      const contentUrl = resolveMediaUrl(data.url || data.path || data.publicUrl);
      const metadata = {
        filename: data.filename || file.name,
        size: data.size || file.size,
        mimeType: data.mimeType || file.type
      };
      await sendMessagePayload({ content: contentUrl, messageType: fileType, metadata });
    } catch (err) {
      console.error('Attachment upload failed:', err);
      toast.error('Failed to upload attachment.');
    } finally {
      event.target.value = '';
    }
  };

  const handleTyping = (e) => {
    setNewMessage(e.target.value);
    if (socket && isConnected && selectedConversation && !isTyping) {
      setIsTyping(true);
      socket.emit('typing_start', { conversationId: selectedConversation.id });
    }
    clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      if (socket && isConnected && selectedConversation) {
        setIsTyping(false);
        socket.emit('typing_stop', { conversationId: selectedConversation.id });
      }
    }, 2000);
  };

  const formatTime = (timestamp) => {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const formatTimeAgo = (timestamp) => {
    if (!timestamp) return '';
    const now = new Date();
    const date = new Date(timestamp);
    const diff = Math.floor((now - date) / 1000);
    if (diff < 60) return 'Just now';
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return date.toLocaleDateString();
  };

  // Handle voice call — delegates to CallSystem via CallContext
  const handleVoiceCall = () => {
    if (!selectedConversation) return;
    triggerCall(selectedConversation.participantId, 'audio', selectedConversation.participantName);
  };

  // Handle video call — delegates to CallSystem via CallContext
  const handleVideoCall = () => {
    if (!selectedConversation) return;
    triggerCall(selectedConversation.participantId, 'video', selectedConversation.participantName);
  };

  // View user profile
  const handleViewProfile = () => {
    if (selectedConversation?.participantId) {
      navigate(`/profile/${selectedConversation.participantId}`);
    }
    setMenuAnchorEl(null);
  };

  // Open more menu
  const handleMenuOpen = (event) => {
    setMenuAnchorEl(event.currentTarget);
  };

  // Close menu
  const handleMenuClose = () => {
    setMenuAnchorEl(null);
  };

  // Block user
  const handleBlockUser = async () => {
    if (!selectedConversation?.participantId) return;
    
    try {
      const token = localStorage.getItem('token');
      await fetch(`${API_BASE_URL}/chat/block-user`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ userId: selectedConversation.participantId })
      });
      // Remove conversation from list
      setConversations(prev => prev.filter(c => c.id !== selectedConversation.id));
      setSelectedConversation(null);
      setShowMobileChat(false);
    } catch (error) {
      console.error('Failed to block user:', error);
    }
    setMenuAnchorEl(null);
  };

  // Report user
  const handleReportUser = () => {
    if (selectedConversation?.participantId) {
      navigate(`/report?userId=${selectedConversation.participantId}&type=user`);
    }
    setMenuAnchorEl(null);
  };

  // Delete conversation
  const handleDeleteConversation = async () => {
    if (!selectedConversation) return;
    
    try {
      const token = localStorage.getItem('token');
      await fetch(`${API_BASE_URL}/chat/conversations/${selectedConversation.id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setConversations(prev => prev.filter(c => c.id !== selectedConversation.id));
      setSelectedConversation(null);
      setShowMobileChat(false);
    } catch (error) {
      console.error('Failed to delete conversation:', error);
    }
    setMenuAnchorEl(null);
  };

  // Delete conversation by ID (for swipe action)
  const handleDeleteConversationById = async (conversationId) => {
    try {
      const token = localStorage.getItem('token');
      await fetch(`${API_BASE_URL}/chat/conversations/${conversationId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setConversations(prev => prev.filter(c => c.id !== conversationId));
      if (selectedConversation?.id === conversationId) {
        setSelectedConversation(null);
        setShowMobileChat(false);
      }
    } catch (error) {
      console.error('Failed to delete conversation:', error);
    }
    setSwipedConversationId(null);
  };

  // Mark conversation as read (swipe right action)
  const handleMarkAsRead = async (conversationId) => {
    try {
      await markConversationRead(conversationId);
      setConversations(prev => prev.map(c => 
        c.id === conversationId ? { ...c, unreadCount: 0 } : c
      ));
    } catch (error) {
      console.error('Failed to mark as read:', error);
    }
    setSwipedConversationId(null);
  };

  // Check for active escrow and pending milestones when conversation changes
  // Use participantId (primitive) instead of the full selectedConversation object
  // to avoid re-fetching when only participantOnline or other fields change.
  const selectedParticipantId = selectedConversation?.participantId || null;
  useEffect(() => {
    const checkActiveEscrow = async () => {
      if (!selectedParticipantId) {
        setActiveEscrow(null);
        setPendingMilestones([]);
        return;
      }
      try {
        const token = localStorage.getItem('token');
        
        // Check escrow
        const escrowResponse = await fetch(`${API_BASE_URL}/escrow/list`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (escrowResponse.ok) {
          const data = await escrowResponse.json();
          // Find escrow with this participant
          const escrow = (data.escrows || []).find(e => 
            (e.provider_id === selectedParticipantId || 
             e.client_id === selectedParticipantId) &&
            e.status === 'held'
          );
          setActiveEscrow(escrow || null);
          
          // Check if current user is the provider in any escrow
          const isUserProvider = (data.escrows || []).some(e => e.provider_id === user?.id);
          setIsProvider(isUserProvider);
        }
        
        // Check pending milestone requests
        const milestoneResponse = await fetch(`${API_BASE_URL}/milestone/pending/${selectedParticipantId}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (milestoneResponse.ok) {
          const milestoneData = await milestoneResponse.json();
          setPendingMilestones(milestoneData.requests || []);
        }
      } catch (error) {
        console.error('Failed to check escrow/milestones:', error);
      }
    };
    checkActiveEscrow();
  }, [selectedParticipantId, user?.id]);

  // Handle escrow payment success
  const handlePaymentSuccess = (escrowData) => {
    setActiveEscrow(escrowData);
    setPaymentSheetOpen(false);
    // Update conversation to show escrow active
    if (selectedConversation) {
      setConversations(prev => prev.map(c => 
        c.id === selectedConversation.id 
          ? { ...c, hasActiveEscrow: true, escrowAmount: escrowData.amount }
          : c
      ));
      setSelectedConversation(prev => prev ? { ...prev, hasActiveEscrow: true, escrowAmount: escrowData.amount } : prev);
    }
  };

  // Release payment (confirm service completed)
  const handleReleasePayment = async () => {
    if (!activeEscrow) return;
    setEscrowLoading(true);
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/escrow/complete`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ escrowId: activeEscrow.id })
      });
      if (response.ok) {
        setActiveEscrow(null);
        // Update conversation
        if (selectedConversation) {
          setConversations(prev => prev.map(c => 
            c.id === selectedConversation.id 
              ? { ...c, hasActiveEscrow: false, escrowAmount: null }
              : c
          ));
          setSelectedConversation(prev => prev ? { ...prev, hasActiveEscrow: false, escrowAmount: null } : prev);
        }
        toast.success('Payment released! The provider has received the funds.');
      } else {
        toast.error('Failed to release payment. Please try again.');
      }
    } catch (error) {
      console.error('Failed to release payment:', error);
      toast.error('Error releasing payment.');
    } finally {
      setEscrowLoading(false);
    }
  };

  // Report a problem with the escrow — opens dispute dialog
  const handleReportProblem = () => {
    if (!activeEscrow) return;
    setDisputeReason('');
    setDisputeDialogOpen(true);
  };

  // Submit dispute after dialog confirmation
  const handleSubmitDispute = async () => {
    if (!activeEscrow || !disputeReason.trim()) return;
    setDisputeDialogOpen(false);
    
    setEscrowLoading(true);
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/escrow/dispute`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ escrowId: activeEscrow.id, reason: disputeReason.trim() })
      });
      if (response.ok) {
        setActiveEscrow(prev => prev ? { ...prev, status: 'disputed' } : null);
        toast.info('Issue reported. Our support team will review and contact you soon.');
      } else {
        toast.error('Failed to report issue. Please try again.');
      }
    } catch (error) {
      console.error('Failed to report problem:', error);
      toast.error('Error reporting issue.');
    } finally {
      setEscrowLoading(false);
    }
  };

  // Handle milestone request success
  const handleMilestoneRequestSuccess = (data) => {
    setPendingMilestones(prev => [...prev, data.request]);
    setMilestoneDialogOpen(false);
    toast.success('Payment request sent!');
  };

  // Accept milestone request
  const handleAcceptMilestone = async (requestId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/milestone/respond`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ requestId, action: 'accept' })
      });
      if (response.ok) {
        setPendingMilestones(prev => prev.map(m => 
          m.id === requestId ? { ...m, status: 'accepted' } : m
        ));
      }
    } catch (error) {
      console.error('Failed to accept milestone:', error);
      toast.error('Failed to accept request');
    }
  };

  // Decline milestone request
  const handleDeclineMilestone = async (requestId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/milestone/respond`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ requestId, action: 'decline' })
      });
      if (response.ok) {
        setPendingMilestones(prev => prev.filter(m => m.id !== requestId));
      }
    } catch (error) {
      console.error('Failed to decline milestone:', error);
      toast.error('Failed to decline request');
    }
  };

  // Pay for accepted milestone
  const handlePayMilestone = async (request) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE_URL}/milestone/pay`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ requestId: request.id })
      });
      if (response.ok) {
        const data = await response.json();
        setActiveEscrow(data.escrow);
        setPendingMilestones(prev => prev.filter(m => m.id !== request.id));
        toast.success('Payment held successfully!');
      }
    } catch (error) {
      console.error('Failed to pay milestone:', error);
      toast.error('Payment failed. Try again.');
    }
  };

  const filteredConversations = conversations.filter(conv =>
    conv.participantName?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const markConversationRead = async (conversationId) => {
    try {
      const token = localStorage.getItem('token');
      await fetch(`${API_BASE_URL}/chat/read/${conversationId}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      // NOTE: The REST endpoint already emits 'message_read' via socket.
      // Do NOT also emit 'mark_read' here — that causes double emission
      // (4 events per read to the other participant).
    } catch (error) {
      console.error('Failed to mark conversation read:', error);
    }
  };

  const selectConversation = (conv) => {
    if (!conv) return;
    const decrementBy = Number(conv.unreadCount || 0);
    const isTargetRecipient = normalizeId(conv.participantId) === normalizeId(targetRecipientId);
    const mergedConv = {
      ...conv,
      participantName: conv.participantName || (isTargetRecipient ? targetRecipientName : conv.participantName),
      participantAvatar: conv.participantAvatar || (isTargetRecipient ? targetRecipientAvatar : conv.participantAvatar)
    };
    setSelectedConversation(mergedConv);
    setShowMobileChat(true);
    setConversations(prev => prev.map(c => c.id === conv.id ? { ...c, unreadCount: 0 } : c));
    markConversationRead(conv.id);

    // Keep global unread badge in sync when a thread is opened.
    if (decrementBy > 0) {
      dispatch(decrementUnreadMessages(decrementBy));
    }
  };

  const handleBackToList = () => {
    setShowMobileChat(false);
    setSelectedConversation(null);
  };

  if (!user) return null;

  return (
    <Box sx={styles.container}>
      {/* Chat Area - center; full width on mobile when open */}
      <Box sx={{ ...styles.chatArea, display: { xs: showMobileChat ? 'flex' : 'none', md: 'flex' } }}>
        {selectedConversation ? (
          <>
            {/* Chat Header */}
            <Box sx={styles.chatHeader}>
              <IconButton 
                sx={{ ...styles.backBtn, display: { xs: 'flex', md: 'none' } }}
                onClick={handleBackToList}
                aria-label="Back to conversations"
              >
                <BackIcon />
              </IconButton>
              <Box 
                sx={{ ...styles.chatHeaderInfo, cursor: 'pointer' }}
                onClick={handleViewProfile}
                title="View Profile"
              >
                <Avatar src={selectedConversation.participantAvatar} sx={styles.chatAvatar}>
                  {selectedConversation.participantName?.[0]}
                </Avatar>
                <Box>
                  <Typography sx={styles.chatUserName}>
                    {selectedConversation.participantName}
                  </Typography>
                  <Typography sx={styles.chatUserStatus}>
                    {remoteTyping ? 'Typing…' : selectedConversation.participantOnline ? 'Online' : 'Offline'}
                  </Typography>
                </Box>
              </Box>
              <Box sx={styles.chatHeaderActions}>
                {/* Video Call - WhatsApp shows this on mobile */}
                <IconButton 
                  sx={styles.headerActionBtn}
                  onClick={handleVideoCall}
                  title="Video Call"
                  aria-label="Start video call"
                >
                  <VideoIcon />
                </IconButton>
                {/* Voice Call - WhatsApp shows this on mobile */}
                <IconButton 
                  sx={styles.headerActionBtn}
                  onClick={handleVoiceCall}
                  title="Voice Call"
                  aria-label="Start voice call"
                >
                  <PhoneIcon />
                </IconButton>
                <IconButton 
                  sx={styles.headerActionBtn}
                  onClick={handleMenuOpen}
                  title="More Options"
                  aria-label="Open conversation options menu"
                >
                  <MoreIcon />
                </IconButton>
              </Box>
              
              {/* More Options Menu */}
              <Menu
                anchorEl={menuAnchorEl}
                open={menuOpen}
                onClose={handleMenuClose}
                PaperProps={{
                  sx: {
                    bgcolor: '#1f2c34', // WhatsApp dark
                    border: 'none',
                    borderRadius: '8px',
                    '& .MuiMenuItem-root': {
                      color: '#fff',
                      gap: 1.5,
                      minHeight: 44,
                      fontSize: '15px',
                      '&:hover': { bgcolor: 'rgba(255,255,255,0.08)' }
                    }
                  }
                }}
              >
                {/* Call options removed from menu - now in header */}
                <MenuItem onClick={handleViewProfile}>
                  <PersonIcon fontSize="small" /> View Profile
                </MenuItem>
                <MenuItem onClick={handleBlockUser} sx={{ color: '#ff6b6b !important' }}>
                  <BlockIcon fontSize="small" /> Block User
                </MenuItem>
                <MenuItem onClick={handleReportUser} sx={{ color: '#ffa726 !important' }}>
                  <ReportIcon fontSize="small" /> Report
                </MenuItem>
                <MenuItem onClick={handleDeleteConversation} sx={{ color: '#ff6b6b !important' }}>
                  <DeleteIcon fontSize="small" /> Delete Chat
                </MenuItem>
              </Menu>
            </Box>

            {/* Escrow Bar - Shows when money is held */}
            {activeEscrow && (
              <Box sx={styles.escrowBar}>
                <LockIcon sx={{ fontSize: 18 }} />
                <Typography sx={{ fontWeight: 500 }}>
                  Money Held: {activeEscrow.currency || ''}{Number(activeEscrow.amount).toLocaleString()}
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                  <Chip
                    icon={<CheckCircleIcon />}
                    label="Release"
                    onClick={handleReleasePayment}
                    disabled={escrowLoading}
                    sx={{
                      bgcolor: 'rgba(0, 255, 136, 0.2)',
                      color: '#00ff88',
                      fontWeight: 600,
                      '&:hover': { bgcolor: 'rgba(0, 255, 136, 0.3)' }
                    }}
                  />
                  <Chip
                    icon={<WarningIcon />}
                    label="Problem"
                    onClick={handleReportProblem}
                    disabled={escrowLoading}
                    sx={{
                      bgcolor: 'rgba(255, 167, 38, 0.2)',
                      color: '#ffa726',
                      fontWeight: 600,
                      '&:hover': { bgcolor: 'rgba(255, 167, 38, 0.3)' }
                    }}
                  />
                </Box>
              </Box>
            )}

            {/* Messages */}
            <Box 
              ref={messagesContainerRef}
              sx={styles.messagesContainer}
              role="log"
              aria-live="polite"
              aria-label="Chat messages"
              onScroll={handleMessagesScroll}
            >
              {messages.map((message, index) => (
                <motion.div
                  key={message.id || message._id || `msg-${message.senderId}-${message.created_at || index}`}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.2 }}
                >
                  <Box
                    sx={{
                      ...styles.messageRow,
                      justifyContent: String(message.senderId || '') === currentUserId ? 'flex-end' : 'flex-start'
                    }}
                  >
                    <Box
                      sx={{
                        ...styles.messageBubble,
                        ...(String(message.senderId || '') === currentUserId ? styles.sentBubble : styles.receivedBubble),
                        cursor: 'pointer',
                        userSelect: 'none',
                        WebkitUserSelect: 'none',
                        WebkitTouchCallout: 'none'
                      }}
                      onContextMenu={(e) => {
                        e.preventDefault();
                        setSelectedMessage(message);
                        setMessageMenuAnchor({ mouseX: e.clientX, mouseY: e.clientY });
                      }}
                      onTouchStart={() => {
                        longPressTimer.current = setTimeout(() => {
                          setSelectedMessage(message);
                          setMessageMenuAnchor({ mouseX: null, mouseY: null });
                        }, 500);
                      }}
                      onTouchEnd={() => {
                        if (longPressTimer.current) {
                          clearTimeout(longPressTimer.current);
                        }
                      }}
                      onTouchMove={() => {
                        if (longPressTimer.current) {
                          clearTimeout(longPressTimer.current);
                        }
                      }}
                    >
                      {(() => {
                        // Infer message type from content when messageType is missing or 'text'
                        const effectiveType = inferMessageTypeFromContent(
                          message.content,
                          message.messageType,
                          message.metadata || {}
                        );
                        if (effectiveType === 'image') {
                          return (
                            <Box
                              component="img"
                              src={resolveMediaUrl(message.content)}
                              alt="Shared image"
                              sx={{ maxWidth: '100%', maxHeight: 300, borderRadius: 1, cursor: 'pointer' }}
                              onClick={() => window.open(resolveMediaUrl(message.content), '_blank')}
                            />
                          );
                        }
                        if (effectiveType === 'video') {
                          return (
                            <Box
                              component="video"
                              src={resolveMediaUrl(message.content)}
                              controls
                              playsInline
                              preload="metadata"
                              sx={{ maxWidth: '100%', maxHeight: 300, borderRadius: 1 }}
                            />
                          );
                        }
                        if (effectiveType === 'audio') {
                          return (
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 200 }}>
                              <Box
                                component="audio"
                                src={resolveMediaUrl(message.content)}
                                controls
                                preload="metadata"
                                sx={{ width: '100%', maxWidth: 280, height: 40 }}
                              />
                            </Box>
                          );
                        }
                        if (effectiveType === 'file') {
                          return (
                            <Box
                              component="a"
                              href={resolveMediaUrl(message.content)}
                              target="_blank"
                              rel="noopener noreferrer"
                              sx={{ color: 'inherit', textDecoration: 'underline', display: 'flex', alignItems: 'center', gap: 0.5 }}
                            >
                              <AttachIcon sx={{ fontSize: 16 }} />
                              <Typography sx={styles.messageText}>
                                {message.metadata?.fileName || message.metadata?.filename || 'Download file'}
                              </Typography>
                            </Box>
                          );
                        }
                        // Default: plain text
                        return <Typography sx={styles.messageText}>{message.content}</Typography>;
                      })()}
                      <Box sx={styles.messageFooter}>
                        <Typography sx={styles.messageTime}>
                          {formatTime(message.createdAt)}
                        </Typography>
                        {String(message.senderId || '') === currentUserId && (
                          message.status === 'sending' ? (
                            <CheckIcon sx={{ fontSize: 14, opacity: 0.5 }} />
                          ) : message.readAt ? (
                            <DoneAllIcon sx={{ fontSize: 14, color: '#00f2ea' }} />
                          ) : (
                            <DoneAllIcon sx={{ fontSize: 14, opacity: 0.5 }} />
                          )
                        )}
                      </Box>
                    </Box>
                  </Box>
                </motion.div>
              ))}
              <div ref={messagesEndRef} />
              
              {/* Scroll to bottom FAB */}
              {showScrollButton && (
                <Fab
                  size="small"
                  aria-label="Scroll to latest messages"
                  onClick={scrollToBottom}
                  sx={{
                    position: 'absolute',
                    bottom: 90,
                    right: 16,
                    background: 'rgba(0, 242, 234, 0.95)',
                    color: '#000',
                    width: 44,
                    height: 44,
                    boxShadow: '0 4px 12px rgba(0,242,234,0.4)',
                    '&:hover': {
                      background: '#00f2ea'
                    }
                  }}
                >
                  <KeyboardArrowDownIcon />
                </Fab>
              )}
            </Box>

            {/* Pending Milestone Requests */}
            {pendingMilestones.length > 0 && (
              <Box sx={styles.milestoneRequestsArea}>
                {pendingMilestones.map((request) => (
                  <MilestoneRequestCard
                    key={request.id}
                    request={request}
                    currentUserId={user?.id}
                    onAccept={handleAcceptMilestone}
                    onDecline={handleDeclineMilestone}
                    onPay={handlePayMilestone}
                  />
                ))}
              </Box>
            )}

            {/* Input Area */}
            {selectedConversation && (
              <Box sx={styles.inputArea}>
                <input
                  ref={fileInputRef}
                  type="file"
                  style={{ display: 'none' }}
                  accept="image/*,video/*"
                  onChange={handleFilePreview}
                />
                
                {/* More Actions Button (shows drawer with payment options on mobile) */}
                <IconButton 
                  sx={{
                    ...styles.inputActionBtn,
                    display: { xs: 'flex', sm: 'none' }
                  }}
                  onClick={() => setMoreActionsOpen(true)}
                  aria-label="More actions"
                >
                  <AddIcon />
                </IconButton>
                
                {/* Desktop: Show payment buttons inline */}
                {/* Request Payment button - for sending milestone requests */}
                {!activeEscrow && pendingMilestones.length === 0 && (
                  <IconButton 
                    sx={{
                      ...styles.requestBtn,
                      background: 'linear-gradient(135deg, #ffd700, #ffaa00)',
                      color: '#000',
                      display: { xs: 'none', sm: 'flex' }
                    }} 
                    onClick={() => setMilestoneDialogOpen(true)}
                    title={isProvider ? "Request Payment" : "Request Hold"}
                    aria-label={isProvider ? "Request payment from client" : "Request escrow hold"}
                  >
                    <RequestIcon />
                  </IconButton>
                )}
                {/* Pay Now button - only show if no active escrow */}
                {!activeEscrow && (
                  <IconButton 
                    sx={{
                      ...styles.payNowBtn,
                      background: 'linear-gradient(135deg, #00ff88, #00cc6a)',
                      color: '#000',
                      display: { xs: 'none', sm: 'flex' }
                    }} 
                    onClick={() => setPaymentSheetOpen(true)}
                    title="Hold Money"
                    aria-label="Open payment to hold money in escrow"
                  >
                    <WalletIcon />
                  </IconButton>
                )}
                {/* Attachment button - always visible */}
                <IconButton 
                  sx={{
                    ...styles.inputActionBtn,
                    display: { xs: 'none', sm: 'flex' }
                  }}
                  onClick={() => fileInputRef.current?.click()}
                  title="Attach file"
                  aria-label="Attach photo or video file"
                >
                  <AttachIcon />
                </IconButton>
                <TextField
                  fullWidth
                  variant="outlined"
                  placeholder="Type a message..."
                  value={newMessage}
                  onChange={handleTyping}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      sendMessage();
                    }
                  }}
                  sx={styles.messageInput}
                  multiline
                  maxRows={4}
                  inputProps={{
                    'aria-label': 'Type a message'
                  }}
                  InputProps={{
                    sx: {
                      '& fieldset': { border: 'none !important' }
                    }
                  }}
                />
                <IconButton
                  sx={{
                    ...styles.inputActionBtn,
                    display: { xs: 'none', sm: 'flex' }
                  }}
                  title="Emoji"
                  aria-label="Open emoji picker"
                  onClick={(e) => setEmojiAnchorEl(e.currentTarget)}
                >
                  <EmojiIcon />
                </IconButton>
                <Menu
                  anchorEl={emojiAnchorEl}
                  open={emojiMenuOpen}
                  onClose={() => setEmojiAnchorEl(null)}
                  PaperProps={{
                    sx: {
                      bgcolor: 'rgba(20, 20, 30, 0.98)',
                      border: '1px solid rgba(255,255,255,0.12)',
                      borderRadius: '14px',
                      backdropFilter: 'blur(18px)',
                      '& .MuiMenuItem-root': {
                        color: '#fff',
                        fontSize: 20,
                        minHeight: 44,
                        borderRadius: '10px',
                        '&:hover': { bgcolor: 'rgba(0,242,234,0.10)' }
                      }
                    }
                  }}
                >
                  {['😀', '😂', '😍', '😘', '🔥', '👍', '🙏', '💯'].map((emo) => (
                    <MenuItem
                      key={emo}
                      onClick={() => {
                        setNewMessage((prev) => `${prev || ''}${emo}`);
                        setEmojiAnchorEl(null);
                      }}
                    >
                      {emo}
                    </MenuItem>
                  ))}
                </Menu>
                {/* Always show Send button, disabled when empty */}
                <IconButton 
                  sx={{
                    ...styles.sendBtn,
                    opacity: newMessage.trim() ? 1 : 0.5,
                    cursor: newMessage.trim() ? 'pointer' : 'default'
                  }} 
                  onClick={sendMessage}
                  disabled={!newMessage.trim()}
                  title="Send message"
                  aria-label="Send message"
                >
                  <SendIcon />
                </IconButton>
              </Box>
            )}
          </>
        ) : (
          <Box sx={styles.noChatSelected}>
            <Box sx={styles.noChatIcon}>💬</Box>
            <Typography sx={styles.noChatTitle}>Select a conversation</Typography>
            <Typography sx={styles.noChatSubtitle}>
              Choose from your existing conversations or start a new one
            </Typography>
            <Button
              variant="contained"
              onClick={() => navigate('/profiles')}
              sx={styles.primaryCta}
            >
              Find people to chat
            </Button>
          </Box>
        )}
      </Box>

      {/* Conversations List - TikTok Inbox Style */}
      <Box sx={{ ...styles.conversationsList, display: showMobileChat ? { xs: 'none', md: 'flex' } : 'flex' }}>
        {/* TikTok-style header */}
        <Box sx={styles.listHeader}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <AddIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 24 }} />
          </Box>
          <Typography sx={styles.listTitle}>Inbox</Typography>
          <IconButton 
            onClick={() => {/* Could open search overlay */}}
            sx={{ color: '#fff', p: 0.5 }}
          >
            <SearchIcon sx={{ fontSize: 24 }} />
          </IconButton>
        </Box>

        {/* Search - Hidden by default, TikTok uses overlay */}
        <Box sx={{ ...styles.searchContainer, display: searchQuery ? 'block' : 'none' }}>
          <TextField
            fullWidth
            placeholder="Search conversations..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            sx={styles.searchInput}
            inputProps={{
              'aria-label': 'Search conversations'
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon sx={{ color: 'rgba(255,255,255,0.4)' }} />
                </InputAdornment>
              ),
              endAdornment: searchQuery && (
                <InputAdornment position="end">
                  <IconButton
                    size="small"
                    onClick={() => setSearchQuery('')}
                    aria-label="Clear search"
                    sx={{ 
                      color: 'rgba(255,255,255,0.5)',
                      minWidth: 44,
                      minHeight: 44,
                      '&:hover': { color: '#fff' }
                    }}
                  >
                    <ClearIcon fontSize="small" />
                  </IconButton>
                </InputAdornment>
              )
            }}
          />
        </Box>

        {/* Conversations */}
        <Box 
          sx={styles.conversationsScroll}
          role="list"
          aria-label="Conversations"
        >
          {loading ? (
            <Box sx={styles.loadingContainer}>
              <CircularProgress size={32} sx={{ color: '#00f2ea' }} />
            </Box>
          ) : filteredConversations.length === 0 && searchQuery ? (
            <Box sx={styles.emptyState}>
              <SearchOffIcon sx={{ fontSize: 48, color: 'rgba(255,255,255,0.3)', mb: 1 }} />
              <Typography sx={styles.emptyText}>No results found</Typography>
              <Typography sx={styles.emptySubtext}>
                Try a different search term or clear your search.
              </Typography>
              <Button
                variant="outlined"
                size="small"
                onClick={() => setSearchQuery('')}
                sx={{ 
                  mt: 2, 
                  borderColor: 'rgba(0,242,234,0.4)', 
                  color: '#00f2ea',
                  minHeight: 44,
                  '&:hover': { borderColor: '#00f2ea', background: 'rgba(0,242,234,0.08)' }
                }}
              >
                Clear Search
              </Button>
            </Box>
          ) : filteredConversations.length === 0 ? (
            <Box sx={styles.emptyState}>
              <Typography sx={styles.emptyText}>No conversations yet</Typography>
              <Typography sx={styles.emptySubtext}>Start by browsing profiles and sending a message.</Typography>
              <Button
                variant="contained"
                onClick={() => navigate('/profiles')}
                sx={styles.primaryCta}
              >
                Explore Profiles
              </Button>
            </Box>
          ) : (
            <AnimatePresence>
              {filteredConversations.map((conv, index) => (
                <motion.div
                  key={conv.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, x: -100 }}
                  transition={{ duration: 0.2 }}
                >
                  <SwipeableConversationItem
                    conversationId={conv.id}
                    swipedId={swipedConversationId}
                    setSwipedId={setSwipedConversationId}
                    hasUnread={conv.unreadCount > 0}
                    onSwipeLeft={() => handleDeleteConversationById(conv.id)}
                    onSwipeRight={() => handleMarkAsRead(conv.id)}
                  >
                    <Box
                      role="listitem"
                      tabIndex={0}
                      aria-label={`Conversation with ${conv.participantName}${conv.unreadCount > 0 ? `, ${conv.unreadCount} unread messages` : ''}`}
                      sx={{
                        ...styles.conversationItem,
                        background: selectedConversation?.id === conv.id ? 'rgba(0, 242, 234, 0.18)' : 'transparent'
                      }}
                      onClick={() => {
                        if (swipedConversationId === conv.id) {
                          setSwipedConversationId(null);
                        } else {
                          selectConversation(conv);
                        }
                      }}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          selectConversation(conv);
                        }
                      }}
                    >
                      <Badge
                        overlap="circular"
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                        badgeContent={
                          conv.participantOnline && (
                            <Box sx={styles.onlineBadge} />
                          )
                        }
                      >
                        <Avatar src={conv.participantAvatar} sx={styles.avatar}>
                          {conv.participantName?.[0]}
                        </Avatar>
                      </Badge>
                      <Box sx={styles.conversationInfo}>
                        <Box sx={styles.conversationHeader}>
                          <Typography sx={styles.conversationName}>
                            {conv.participantName}
                            {conv.participantVerified && (
                              <Box component="span" sx={styles.verifiedIcon}>✓</Box>
                            )}
                          </Typography>
                          <Typography sx={styles.conversationTime}>
                            {formatTimeAgo(conv.lastMessageTime)}
                          </Typography>
                        </Box>
                        {typingConversations.includes(conv.id) ? (
                          <Box sx={styles.typingIndicator}>
                            <Box sx={styles.typingDot} />
                            <Box sx={styles.typingDot} />
                            <Box sx={styles.typingDot} />
                          </Box>
                        ) : (
                          <Typography sx={styles.conversationPreview} noWrap>
                            {conv.lastMessage || 'Start a conversation'}
                          </Typography>
                        )}
                      </Box>
                      {conv.unreadCount > 0 && (
                        <Box sx={styles.unreadBadge}>{conv.unreadCount}</Box>
                      )}
                      {conv.hasActiveEscrow && (
                        <Box sx={styles.escrowIndicator}>
                          <LockIcon sx={{ fontSize: 14 }} />
                        </Box>
                      )}
                    </Box>
                  </SwipeableConversationItem>
                </motion.div>
              ))}
            </AnimatePresence>
          )}
        </Box>
      </Box>
      
      {/* Calls are now handled entirely by CallSystem via CallContext */}

      {/* Payment Sheet - Bottom drawer for holding money */}
      <PaymentSheet
        open={paymentSheetOpen}
        onClose={() => setPaymentSheetOpen(false)}
        providerId={selectedConversation?.participantId}
        providerName={selectedConversation?.participantName}
        conversationId={selectedConversation?.id}
        onSuccess={handlePaymentSuccess}
      />

      {/* Milestone Request Dialog */}
      <MilestoneRequestDialog
        open={milestoneDialogOpen}
        onClose={() => setMilestoneDialogOpen(false)}
        recipientId={selectedConversation?.participantId}
        recipientName={selectedConversation?.participantName}
        isProvider={isProvider}
        onSuccess={handleMilestoneRequestSuccess}
      />

      {/* Dispute Report Dialog */}
      <Dialog
        open={disputeDialogOpen}
        onClose={() => setDisputeDialogOpen(false)}
        PaperProps={{ sx: { background: 'rgba(20, 20, 30, 0.98)', color: '#fff', borderRadius: '16px', minWidth: 320 } }}
      >
        <DialogTitle sx={{ color: '#fff' }}>Report a Problem</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 2, color: 'rgba(255,255,255,0.7)' }}>
            Briefly describe what went wrong with this escrow transaction.
          </Typography>
          <TextField
            autoFocus
            fullWidth
            multiline
            minRows={3}
            maxRows={6}
            value={disputeReason}
            onChange={(e) => setDisputeReason(e.target.value)}
            placeholder="What went wrong?"
            inputProps={{ maxLength: 1000 }}
            sx={{
              '& .MuiOutlinedInput-root': {
                color: '#fff',
                '& fieldset': { borderColor: 'rgba(255,255,255,0.3)' },
                '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                '&.Mui-focused fieldset': { borderColor: '#00f2ea' },
              },
            }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDisputeDialogOpen(false)} sx={{ color: 'rgba(255,255,255,0.7)' }}>
            Cancel
          </Button>
          <Button
            onClick={handleSubmitDispute}
            disabled={!disputeReason.trim()}
            variant="contained"
            sx={{ bgcolor: '#ff4444', '&:hover': { bgcolor: '#cc0000' } }}
          >
            Submit Report
          </Button>
        </DialogActions>
      </Dialog>

      {/* Mobile Actions Drawer */}
      <Drawer
        anchor="bottom"
        open={moreActionsOpen}
        onClose={() => setMoreActionsOpen(false)}
        PaperProps={{
          sx: {
            background: 'rgba(20, 20, 30, 0.98)',
            borderTopLeftRadius: '20px',
            borderTopRightRadius: '20px',
            backdropFilter: 'blur(20px)',
            paddingBottom: 'env(safe-area-inset-bottom)',
            maxHeight: '60vh'
          }
        }}
      >
        <Box sx={{ p: 2 }}>
          <Box sx={{ 
            width: 40, 
            height: 4, 
            background: 'rgba(255,255,255,0.3)', 
            borderRadius: 2, 
            mx: 'auto', 
            mb: 2 
          }} />
          <Typography sx={{ color: '#fff', fontWeight: 600, mb: 2, textAlign: 'center' }}>
            Actions
          </Typography>
          
          {!activeEscrow && pendingMilestones.length === 0 && (
            <MenuItem 
              onClick={() => {
                setMoreActionsOpen(false);
                setMilestoneDialogOpen(true);
              }}
              sx={{ 
                color: '#fff', 
                borderRadius: '12px', 
                minHeight: 56,
                gap: 2,
                '&:hover': { background: 'rgba(255,215,0,0.1)' }
              }}
            >
              <RequestIcon sx={{ color: '#ffd700' }} />
              <Typography>{isProvider ? 'Request Payment' : 'Request Hold'}</Typography>
            </MenuItem>
          )}
          
          {!activeEscrow && (
            <MenuItem 
              onClick={() => {
                setMoreActionsOpen(false);
                setPaymentSheetOpen(true);
              }}
              sx={{ 
                color: '#fff', 
                borderRadius: '12px', 
                minHeight: 56,
                gap: 2,
                '&:hover': { background: 'rgba(0,255,136,0.1)' }
              }}
            >
              <WalletIcon sx={{ color: '#00ff88' }} />
              <Typography>Hold Money</Typography>
            </MenuItem>
          )}
          
          <MenuItem 
            onClick={() => {
              setMoreActionsOpen(false);
              fileInputRef.current?.click();
            }}
            sx={{ 
              color: '#fff', 
              borderRadius: '12px', 
              minHeight: 56,
              gap: 2,
              '&:hover': { background: 'rgba(0,242,234,0.1)' }
            }}
          >
            <AttachIcon sx={{ color: '#00f2ea' }} />
            <Typography>Attach Photo/Video</Typography>
          </MenuItem>
          
          <MenuItem 
            onClick={(e) => {
              setMoreActionsOpen(false);
              setEmojiAnchorEl(e.currentTarget);
            }}
            sx={{ 
              color: '#fff', 
              borderRadius: '12px', 
              minHeight: 56,
              gap: 2,
              '&:hover': { background: 'rgba(255,255,255,0.05)' }
            }}
          >
            <EmojiIcon sx={{ color: 'rgba(255,255,255,0.8)' }} />
            <Typography>Emoji</Typography>
          </MenuItem>
        </Box>
      </Drawer>

      {/* Message Long-Press Context Menu */}
      <Menu
        open={Boolean(messageMenuAnchor)}
        onClose={() => {
          setMessageMenuAnchor(null);
          setSelectedMessage(null);
        }}
        anchorReference={messageMenuAnchor?.mouseX ? "anchorPosition" : "none"}
        anchorPosition={
          messageMenuAnchor?.mouseX
            ? { top: messageMenuAnchor.mouseY, left: messageMenuAnchor.mouseX }
            : undefined
        }
        sx={{
          // Center menu when no anchor position (mobile long-press)
          ...(!messageMenuAnchor?.mouseX && {
            '& .MuiPaper-root': {
              position: 'fixed',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)'
            }
          })
        }}
        PaperProps={{
          sx: {
            bgcolor: 'rgba(20, 20, 30, 0.98)',
            border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: '14px',
            backdropFilter: 'blur(18px)',
            minWidth: { xs: 'calc(100vw - 64px)', sm: 180 }, // FIXED: Responsive minWidth
            maxWidth: 'calc(100vw - 32px)', // FIXED: Prevent overflow
            '& .MuiMenuItem-root': {
              color: '#fff',
              gap: 1.5,
              minHeight: 48,
              '&:hover': { bgcolor: 'rgba(0,242,234,0.1)' }
            }
          }
        }}
      >
        <MenuItem onClick={() => {
          if (selectedMessage?.content) {
            navigator.clipboard.writeText(selectedMessage.content);
          }
          setMessageMenuAnchor(null);
          setSelectedMessage(null);
        }}>
          <CopyIcon fontSize="small" sx={{ color: '#00f2ea' }} /> Copy
        </MenuItem>
        {normalizeId(selectedMessage?.senderId) === currentUserId && (
          <MenuItem 
            onClick={async () => {
              if (!selectedMessage) return;
              try {
                const token = localStorage.getItem('token');
                await fetch(`${API_BASE_URL}/chat/messages/${selectedMessage.id}`, {
                  method: 'DELETE',
                  headers: { 'Authorization': `Bearer ${token}` }
                });
                setMessages(prev => prev.filter(m => m.id !== selectedMessage.id));
              } catch (error) {
                console.error('Failed to delete message:', error);
              }
              setMessageMenuAnchor(null);
              setSelectedMessage(null);
            }}
            sx={{ color: '#ff6b6b !important' }}
          >
            <DeleteIcon fontSize="small" /> Delete
          </MenuItem>
        )}
      </Menu>

      {/* Attachment Preview Modal */}
      {attachmentPreview && (
        <Box sx={{
          position: 'fixed',
          bottom: 80,
          left: 0,
          right: 0,
          mx: 2,
          p: 2,
          background: 'rgba(20, 20, 30, 0.98)',
          borderRadius: '16px',
          border: '1px solid rgba(0,242,234,0.3)',
          backdropFilter: 'blur(20px)',
          zIndex: 1300,
          display: 'flex',
          alignItems: 'center',
          gap: 2
        }}>
          <Box sx={{ 
            width: 60, 
            height: 60, 
            borderRadius: '10px', 
            overflow: 'hidden',
            flexShrink: 0
          }}>
            {pendingFile?.type?.startsWith('image/') ? (
              <img 
                src={attachmentPreview} 
                alt="Preview" 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
              />
            ) : (
              <Box sx={{ 
                width: '100%', 
                height: '100%', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                background: 'rgba(0,242,234,0.1)'
              }}>
                <AttachIcon sx={{ color: '#00f2ea' }} />
              </Box>
            )}
          </Box>
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography sx={{ color: '#fff', fontWeight: 500, fontSize: '14px' }} noWrap>
              {pendingFile?.name || 'File'}
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.5)', fontSize: '12px' }}>
              {pendingFile?.size ? `${(pendingFile.size / 1024).toFixed(1)} KB` : ''}
            </Typography>
          </Box>
          <IconButton 
            onClick={() => {
              setAttachmentPreview(null);
              setPendingFile(null);
            }}
            sx={{ color: 'rgba(255,255,255,0.7)' }}
          >
            <CloseIcon />
          </IconButton>
          <IconButton 
            onClick={async () => {
              if (pendingFile) {
                // Create a synthetic event for handleFileSelect
                const syntheticEvent = { target: { files: [pendingFile], value: '' } };
                await handleFileSelect(syntheticEvent);
              }
              setAttachmentPreview(null);
              setPendingFile(null);
            }}
            sx={{ 
              background: 'linear-gradient(135deg, #00f2ea, #00c2bb)',
              color: '#000',
              '&:hover': { background: '#00f2ea' }
            }}
          >
            <SendIcon />
          </IconButton>
        </Box>
      )}
    </Box>
  );
};

